#!/bin/bash\n\n# Air-Gapped RAG VPN Setup Script\n# Configures strongSwan IPsec VPN connection to AWS\n\nset -euo pipefail\n\n# Configuration\nSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\nCONFIG_DIR=\"${SCRIPT_DIR}/../config\"\nLOG_FILE=\"/var/log/rag-vpn-setup.log\"\nENVIRONMENT=\"${1:-dev}\"\n\n# Logging function\nlog() {\n    echo \"[$(date '+%Y-%m-%d %H:%M:%S')] $*\" | tee -a \"$LOG_FILE\"\n}\n\n# Error handling\nerror_exit() {\n    log \"ERROR: $1\"\n    exit 1\n}\n\n# Check if running as root\nif [[ $EUID -ne 0 ]]; then\n    error_exit \"This script must be run as root\"\nfi\n\n# Load environment configuration\nif [[ ! -f \"${CONFIG_DIR}/${ENVIRONMENT}.env\" ]]; then\n    error_exit \"Configuration file not found: ${CONFIG_DIR}/${ENVIRONMENT}.env\"\nfi\n\nsource \"${CONFIG_DIR}/${ENVIRONMENT}.env\"\n\n# Validate required variables\nrequired_vars=(\"HOME_IP\" \"VPC_CIDR\" \"VPN_TUNNEL_CIDR\" \"VPN_BGP_ASN\")\nfor var in \"${required_vars[@]}\"; do\n    if [[ -z \"${!var:-}\" ]]; then\n        error_exit \"Required variable $var is not set\"\n    fi\ndone\n\nlog \"Starting VPN setup for environment: $ENVIRONMENT\"\n\n# Install strongSwan if not present\ninstall_strongswan() {\n    log \"Checking strongSwan installation...\"\n    \n    if ! command -v ipsec &> /dev/null; then\n        log \"Installing strongSwan...\"\n        \n        # Detect package manager\n        if command -v apt-get &> /dev/null; then\n            apt-get update\n            apt-get install -y strongswan strongswan-pki\n        elif command -v yum &> /dev/null; then\n            yum install -y strongswan\n        elif command -v dnf &> /dev/null; then\n            dnf install -y strongswan\n        else\n            error_exit \"Unsupported package manager. Please install strongSwan manually.\"\n        fi\n        \n        log \"strongSwan installed successfully\"\n    else\n        log \"strongSwan is already installed\"\n    fi\n}\n\n# Generate VPN configuration\ngenerate_vpn_config() {\n    log \"Generating VPN configuration...\"\n    \n    # Create ipsec.conf\n    cat > /etc/ipsec.conf << EOF\n# Air-Gapped RAG VPN Configuration - ${ENVIRONMENT}\nconfig setup\n    charondebug=\"ike 1, knl 1, cfg 0\"\n    uniqueids=no\n\nconn aws-${ENVIRONMENT}\n    auto=start\n    left=%defaultroute\n    leftid=${HOME_IP}\n    leftsubnet=0.0.0.0/0\n    right=AWS_VPN_GATEWAY_IP  # To be replaced by deployment script\n    rightsubnet=${VPC_CIDR}\n    ike=aes256-sha1-modp1024!\n    esp=aes256-sha1!\n    keyingtries=0\n    ikelifetime=1h\n    lifetime=8h\n    dpddelay=30\n    dpdtimeout=120\n    dpdaction=restart\n    authby=secret\nEOF\n\n    # Create ipsec.secrets with placeholder\n    cat > /etc/ipsec.secrets << EOF\n# Air-Gapped RAG VPN Secrets - ${ENVIRONMENT}\n${HOME_IP} AWS_VPN_GATEWAY_IP : PSK \"VPN_PRE_SHARED_KEY\"  # To be replaced by deployment script\nEOF\n\n    # Set proper permissions\n    chmod 600 /etc/ipsec.secrets\n    chmod 644 /etc/ipsec.conf\n    \n    log \"VPN configuration generated\"\n}\n\n# Configure network settings\nconfigure_network() {\n    log \"Configuring network settings...\"\n    \n    # Enable IP forwarding\n    echo 'net.ipv4.ip_forward = 1' > /etc/sysctl.d/99-rag-vpn.conf\n    sysctl -p /etc/sysctl.d/99-rag-vpn.conf\n    \n    # Configure firewall rules (if iptables is available)\n    if command -v iptables &> /dev/null; then\n        log \"Configuring iptables rules...\"\n        \n        # Allow VPN traffic\n        iptables -A INPUT -p udp --dport 500 -j ACCEPT\n        iptables -A INPUT -p udp --dport 4500 -j ACCEPT\n        iptables -A INPUT -p esp -j ACCEPT\n        \n        # Allow traffic to/from VPC\n        iptables -A INPUT -s \"$VPC_CIDR\" -j ACCEPT\n        iptables -A OUTPUT -d \"$VPC_CIDR\" -j ACCEPT\n        \n        # Save rules (distribution-specific)\n        if command -v iptables-save &> /dev/null; then\n            iptables-save > /etc/iptables/rules.v4 2>/dev/null || \\\n            iptables-save > /etc/sysconfig/iptables 2>/dev/null || \\\n            log \"Warning: Could not save iptables rules\"\n        fi\n    fi\n    \n    log \"Network configuration completed\"\n}\n\n# Create monitoring script\ncreate_monitoring_script() {\n    log \"Creating VPN monitoring script...\"\n    \n    cat > /usr/local/bin/rag-vpn-monitor << 'EOF'\n#!/bin/bash\n\n# VPN Connection Monitor\nLOG_FILE=\"/var/log/rag-vpn-monitor.log\"\nCHECK_INTERVAL=30\n\nlog() {\n    echo \"[$(date '+%Y-%m-%d %H:%M:%S')] $*\" >> \"$LOG_FILE\"\n}\n\ncheck_vpn_status() {\n    if ipsec status | grep -q \"ESTABLISHED\"; then\n        return 0\n    else\n        return 1\n    fi\n}\n\nrestart_vpn() {\n    log \"VPN connection lost, attempting restart...\"\n    ipsec restart\n    sleep 10\n    \n    if check_vpn_status; then\n        log \"VPN connection restored\"\n    else\n        log \"VPN restart failed\"\n    fi\n}\n\nwhile true; do\n    if ! check_vpn_status; then\n        restart_vpn\n    fi\n    sleep $CHECK_INTERVAL\ndone\nEOF\n\n    chmod +x /usr/local/bin/rag-vpn-monitor\n    \n    # Create systemd service for monitoring\n    cat > /etc/systemd/system/rag-vpn-monitor.service << EOF\n[Unit]\nDescription=RAG VPN Connection Monitor\nAfter=strongswan.service\nRequires=strongswan.service\n\n[Service]\nType=simple\nExecStart=/usr/local/bin/rag-vpn-monitor\nRestart=always\nRestartSec=10\nUser=root\n\n[Install]\nWantedBy=multi-user.target\nEOF\n\n    systemctl daemon-reload\n    systemctl enable rag-vpn-monitor.service\n    \n    log \"VPN monitoring configured\"\n}\n\n# Main execution\nmain() {\n    log \"=== Starting VPN Setup ===\"\n    \n    install_strongswan\n    generate_vpn_config\n    configure_network\n    create_monitoring_script\n    \n    # Enable and start strongSwan\n    systemctl enable strongswan\n    systemctl start strongswan\n    \n    log \"=== VPN Setup Complete ===\"\n    log \"Next steps:\"\n    log \"1. Deploy AWS infrastructure to get VPN gateway IP\"\n    log \"2. Run update_vpn_config.sh with the gateway details\"\n    log \"3. Start the VPN connection with: systemctl start rag-vpn-monitor\"\n}\n\n# Run main function\nmain \"$@\"